def merge_intervals(intervals):
    if not intervals:
        return []

    sorted_intervals = sorted(intervals, key=lambda x: (x[0], x[1]))
    merged = [list(sorted_intervals[0])]

    for i in range(1, len(sorted_intervals)):
        start, end = sorted_intervals[i]
        if start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])

    return merged

import heapq


def toposort(nodes, edges):
    node_list = list(dict.fromkeys(nodes))
    adjacency = {node: set() for node in node_list}
    indegree = {node: 0 for node in node_list}

    for source, destination in edges:
        if source == destination:
            raise ValueError("cycle detected")
        if destination not in adjacency[source]:
            adjacency[source].add(destination)
            indegree[destination] += 1

    heap = [node for node in node_list if indegree[node] == 0]
    heapq.heapify(heap)
    order = []

    while heap:
        node = heapq.heappop(heap)
        order.append(node)

        for neighbor in adjacency[node]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(order) != len(node_list):
        raise ValueError("cycle detected")

    return order
